"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef, useState, useCallback } from "react";

interface BackgroundBeamsProps {
    className?: string;
    beamCount?: number;
}

export const BackgroundBeams = ({ className, beamCount = 20 }: BackgroundBeamsProps) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const beamsRef = useRef<
        { x: number; y: number; width: number; height: number; speed: number; opacity: number }[]
    >([]);
    const animationFrameRef = useRef<number>(0);

    const initBeams = useCallback(() => {
        const beams = Array.from({ length: beamCount }, () => ({
            x: Math.random() * 1000,
            y: Math.random() * 1000,
            width: Math.random() * 2 + 0.5,
            height: Math.random() * 200 + 100,
            speed: Math.random() * 2 + 1,
            opacity: Math.random() * 0.3 + 0.1,
        }));
        beamsRef.current = beams;
    }, [beamCount]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        const resizeCanvas = () => {
            canvas.width = canvas.offsetWidth * window.devicePixelRatio;
            canvas.height = canvas.offsetHeight * window.devicePixelRatio;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
        };

        resizeCanvas();
        window.addEventListener("resize", resizeCanvas);
        initBeams();

        const animate = () => {
            ctx.clearRect(0, 0, canvas.offsetWidth, canvas.offsetHeight);

            beamsRef.current.forEach((beam) => {
                const gradient = ctx.createLinearGradient(
                    beam.x,
                    beam.y,
                    beam.x,
                    beam.y + beam.height
                );
                gradient.addColorStop(0, `rgba(120, 120, 120, 0)`);
                gradient.addColorStop(0.5, `rgba(200, 200, 200, ${beam.opacity})`);
                gradient.addColorStop(1, `rgba(120, 120, 120, 0)`);

                ctx.fillStyle = gradient;
                ctx.fillRect(beam.x, beam.y, beam.width, beam.height);

                beam.y += beam.speed;
                if (beam.y > canvas.offsetHeight + beam.height) {
                    beam.y = -beam.height;
                    beam.x = Math.random() * canvas.offsetWidth;
                }
            });

            animationFrameRef.current = requestAnimationFrame(animate);
        };

        // Defer past first paint so the canvas loop doesn't block LCP/FCP
        const startId = setTimeout(animate, 300);

        return () => {
            clearTimeout(startId);
            window.removeEventListener("resize", resizeCanvas);
            cancelAnimationFrame(animationFrameRef.current);
        };
    }, [initBeams]);

    return (
        <canvas
            ref={canvasRef}
            className={cn("absolute inset-0 h-full w-full", className)}
            style={{ zIndex: 0 }}
        />
    );
};
